local MillstoneBushMaker = {}
local PRODUCTS = {
    iron_millstonebush = { name = "Železni ležajni bush za mlinske kamne", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni ležajni bush za mlinske kamne za mlinarje." },
    bronze_millstonebush = { name = "Bronast ležajni bush za mlinske kamne", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast ležajni bush za mlinske kamne za mlinarje." },
    silver_millstonebush = { name = "Srebrn ležajni bush za mlinske kamne", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn ležajni bush za mlinske kamne za mlinarje." },
    gilded_millstonebush = { name = "Pozlačen ležajni bush za mlinske kamne", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen ležajni bush za mlinske kamne za mlinarje." },
    jewel_set_millstonebush = { name = "Draguljast ležajni bush za mlinske kamne", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast ležajni bush za mlinske kamne za mlinarje." },
    royal_sovereign_millstonebush = { name = "Kraljevski suveren ležajni bush za mlinske kamne", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren ležajni bush za mlinske kamne z biseri za krono." },
}
local BUILDINGS = {
    millstonebush_workshop = { name = "Millstonebush delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    millstonebush_house = { name = "Millstonebush hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_millstonebush_atelier = { name = "Mojstrski millstonebush atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_millstonebush_palace = { name = "Suverena millstonebush palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MillstoneBushMaker.ironStock=18; MillstoneBushMaker.bronzeStock=14; MillstoneBushMaker.woodStock=10; MillstoneBushMaker.leatherStock=8; MillstoneBushMaker.silverStock=8; MillstoneBushMaker.goldStock=6; MillstoneBushMaker.jewelStock=4; MillstoneBushMaker.pearlStock=4
MillstoneBushMaker.productStock = {}; MillstoneBushMaker.buildings = {}; MillstoneBushMaker.maker = nil; MillstoneBushMaker.activeMaking = {}; MillstoneBushMaker.totalProducts = 0; MillstoneBushMaker.dayTimer = 0
function MillstoneBushMaker.init() MillstoneBushMaker.ironStock=18; MillstoneBushMaker.bronzeStock=14; MillstoneBushMaker.woodStock=10; MillstoneBushMaker.leatherStock=8; MillstoneBushMaker.silverStock=8; MillstoneBushMaker.goldStock=6; MillstoneBushMaker.jewelStock=4; MillstoneBushMaker.pearlStock=4; MillstoneBushMaker.productStock={}; MillstoneBushMaker.buildings={}; MillstoneBushMaker.maker=nil; MillstoneBushMaker.activeMaking={}; MillstoneBushMaker.totalProducts=0; MillstoneBushMaker.dayTimer=0; print("[MillstoneBushMaker] Royal Millstone Bush Maker System initialized (6 products, 4 buildings)") end
function MillstoneBushMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneBushMaker.maker={name=n or ("Ležajnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ležajnik najet: %s (spretnost: %d)",MillstoneBushMaker.maker.name,s),"success") end; return true end
function MillstoneBushMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneBushMaker.build(id) local ok,e=MillstoneBushMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneBushMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneBushMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneBushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneBushMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneBushMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneBushMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneBushMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneBushMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneBushMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneBushMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneBushMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneBushMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneBushMaker.buildings==0 then return false,"Potrebna ležajna delavnica" end; if not MillstoneBushMaker.maker then return false,"Potreben ležajnik" end; return true end
function MillstoneBushMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneBushMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneBushMaker.ironStock=MillstoneBushMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneBushMaker.bronzeStock=MillstoneBushMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneBushMaker.woodStock=MillstoneBushMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneBushMaker.leatherStock=MillstoneBushMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneBushMaker.silverStock=MillstoneBushMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneBushMaker.goldStock=MillstoneBushMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneBushMaker.jewelStock=MillstoneBushMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneBushMaker.pearlStock=MillstoneBushMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneBushMaker.maker then t=math.max(1,t-math.floor(MillstoneBushMaker.maker.skill/13)) end; table.insert(MillstoneBushMaker.activeMaking,{id="millstonebush_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneBushMaker.completeMaking(m) local q=1.0+(MillstoneBushMaker.getQualityBonus()/100); if MillstoneBushMaker.maker then q=q+(MillstoneBushMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneBushMaker.productStock[m.productType]=(MillstoneBushMaker.productStock[m.productType] or 0)+m.quantity; MillstoneBushMaker.totalProducts=MillstoneBushMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneBushMaker.maker then MillstoneBushMaker.maker.itemsMade=MillstoneBushMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneBushMaker.maker.skill=math.min(100,MillstoneBushMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bush izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonebush.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneBushMaker.update(dt) if not _G.state then return end; MillstoneBushMaker.dayTimer=MillstoneBushMaker.dayTimer+dt; if MillstoneBushMaker.dayTimer>=30 then MillstoneBushMaker.dayTimer=0; for i=#MillstoneBushMaker.activeMaking,1,-1 do local m=MillstoneBushMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneBushMaker.completeMaking(m); table.remove(MillstoneBushMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneBushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneBushMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneBushMaker.getStats() return {ironStock=MillstoneBushMaker.ironStock,bronzeStock=MillstoneBushMaker.bronzeStock,woodStock=MillstoneBushMaker.woodStock,leatherStock=MillstoneBushMaker.leatherStock,silverStock=MillstoneBushMaker.silverStock,goldStock=MillstoneBushMaker.goldStock,jewelStock=MillstoneBushMaker.jewelStock,pearlStock=MillstoneBushMaker.pearlStock,productStock=MillstoneBushMaker.productStock,numBuildings=#MillstoneBushMaker.buildings,hasMaker=MillstoneBushMaker.maker~=nil,makerName=MillstoneBushMaker.maker and MillstoneBushMaker.maker.name or "—",makerSkill=MillstoneBushMaker.maker and MillstoneBushMaker.maker.skill or 0,activeMaking=#MillstoneBushMaker.activeMaking,totalProducts=MillstoneBushMaker.totalProducts} end
return MillstoneBushMaker
